"""Writing generated files without clobbering hand edits.

A generated source file starts with a marker line holding a hash of the rest of the file:

    // @generated by scripts/new-entity.py (scripts/templates/entity/ListPage.tsx) hash:1a2b3c4d. Edit freely: ...

On the next run the file is rewritten only while that hash still matches (nobody edited it). Once edited, it is left
alone and reported, unless --force. Aggregator files (*.gen.ts, entity_routes.py) are always rewritten: they say so.
Locale JSON is merged: generated keys are added or dropped, existing texts (translations, rewording) are kept.
"""

from __future__ import annotations

import hashlib
import json
import re
from pathlib import Path

from . import ROOT

MARK = re.compile(r"@generated by (?P<by>\S+)(?: \((?P<src>[^)]*)\))? hash:(?P<hash>[0-9a-f]{8})")


def digest(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:8]


def rel(path: Path) -> str:
    try:
        return str(path.relative_to(ROOT))
    except ValueError:
        return str(path)


class Writer:
    """Collects what a run did (written / unchanged / kept) for the closing report. `dry`: change nothing."""

    def __init__(self, force: bool = False, dry: bool = False, by: str = "scripts/new-entity.py"):
        self.force, self.dry, self.by = force, dry, by
        self.log: list[tuple[str, str]] = []

    def _put(self, path: Path, text: str, status: str) -> None:
        if not self.dry:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8", newline="\n")
        self.log.append((status, rel(path)))

    def plain(self, path: Path, text: str) -> str:
        """Always (re)write: aggregators and config the generator owns."""
        if path.exists() and path.read_text(encoding="utf-8") == text:
            self.log.append(("unchanged", rel(path)))
            return "unchanged"
        status = "updated" if path.exists() else "created"
        self._put(path, text, status)
        return status

    def once(self, path: Path, text: str) -> str:
        """Write only when missing (fixtures, files the user owns from the start)."""
        if path.exists():
            self.log.append(("exists", rel(path)))
            return "exists"
        self._put(path, text, "created")
        return "created"

    def generated(self, path: Path, body: str, source: str = "", comment: str = "//") -> str:
        """A generated source file with the hash marker; kept when hand-edited (unless force)."""
        note = "Edit freely: once edited, the generator leaves this file alone (--force overwrites)."
        head = f"{comment} @generated by {self.by}{f' ({source})' if source else ''} hash:{digest(body)}. {note}\n"
        text = head + body
        if path.exists():
            old = path.read_text(encoding="utf-8")
            if old == text:
                self.log.append(("unchanged", rel(path)))
                return "unchanged"
            first, _, rest = old.partition("\n")
            m = MARK.search(first)
            edited = not m or m.group("hash") != digest(rest)
            if edited and not self.force:
                self.log.append(("kept (hand-edited; --force to overwrite)", rel(path)))
                return "kept"
            self._put(path, text, "updated")
            return "updated"
        self._put(path, text, "created")
        return "created"

    def locale(self, path: Path, tree: dict, keep_existing: bool = True) -> str:
        """A locale file `{area: {...}}`: the generated keys, with any text already there kept."""
        if path.exists() and keep_existing:
            old = json.loads(path.read_text(encoding="utf-8"))
            tree = merge_texts(tree, old)
        text = json.dumps(tree, indent=2, ensure_ascii=False) + "\n"
        return self.plain(path, text)

    def remove(self, path: Path) -> None:
        if path.exists():
            if not self.dry:
                path.unlink()
            self.log.append(("removed", rel(path)))

    def report(self, quiet_unchanged: bool = True) -> str:
        lines = [f"  {status:<10} {p}" for status, p in self.log if not (quiet_unchanged and status in ("unchanged", "exists"))]
        skipped = sum(1 for s, _ in self.log if s in ("unchanged", "exists"))
        if skipped and quiet_unchanged:
            lines.append(f"  ({skipped} file(s) already up to date)")
        return "\n".join(lines)

    @property
    def kept(self) -> list[str]:
        return [p for s, p in self.log if s.startswith("kept")]


def merge_texts(new: dict, old: dict) -> dict:
    """`new`'s keys, with `old`'s values where both have a text (plural forms of a key are kept together)."""
    out = {}
    for k, v in new.items():
        if isinstance(v, dict):
            out[k] = merge_texts(v, old.get(k) if isinstance(old.get(k), dict) else {})
        else:
            out[k] = old[k] if isinstance(old.get(k), str) else v
    return out


COND = re.compile(r"#(if|else|endif)\b\s*(\w*)")


def conditionals(template: str, flags: dict[str, bool]) -> str:
    """Line blocks between `#if flag` / `#else` / `#endif` marker lines (any comment syntax around them; the marker lines
    themselves go) are kept only when the flag holds. Blocks don't nest."""
    out, keep, inside = [], True, False
    for line in template.splitlines(keepends=True):
        m = COND.search(line)
        if m and line.strip().startswith(("//", "{/*", "#")):
            kind, flag = m.groups()
            if kind == "if":
                if flag not in flags:
                    raise ValueError(f"unknown template flag: {flag}")
                keep, inside = bool(flags[flag]), True
            elif kind == "else":
                keep = not keep
            else:
                keep, inside = True, False
            continue
        if keep or not inside:
            out.append(line)
    return "".join(out)


def render(template: str, values: dict[str, str], flags: dict[str, bool] | None = None) -> str:
    """Keep the #if blocks `flags` allow, then replace __Name__ placeholders (longest first)."""
    template = conditionals(template, flags or {})
    for k in sorted(values, key=len, reverse=True):
        template = template.replace(k, values[k])
    left = [p for p in re.findall(r"__[A-Za-z]+__", template)
            if p not in ("__future__", "__init__", "__name__", "__main__", "__file__", "__doc__")]
    if left:
        raise ValueError(f"unfilled placeholders: {sorted(set(left))}")
    return template
